+import assert from "node:assert";
+import { readFileSync } from "node:fs";
+for (const f of ["server/openai.ts", "main.py", "document_chat_api.py"]) {
+  const src = readFileSync(f, "utf8");
+  assert.ok(!/beta\.(assistants|threads)/.test(src), `${f} still uses Assistants API`);
+  assert.ok(/responses\.create/.test(src), `${f} lacks responses.create`);
+}
+process.env.OPENAI_API_KEY = "x";
+const { openai, createAssistant, createThread, sendMessage } = await import("../server/openai.ts");
+const calls: any[] = [];
+(openai as any).vectorStores.create = async (body: any) => ({ id: "vs_1" });
+(openai as any).responses.create = async (body: any) => {
+  calls.push(body);
+  return { id: `resp_${calls.length}`, status: "completed", output_text: "hi" };
+};
+const a = await createAssistant(["file_1"], "c");
+assert.equal(a.assistantId, "vs_1");
+const t = await createThread("c");
+await sendMessage(t.threadId, a.assistantId, "q1", "c");
+const r = await sendMessage(t.threadId, a.assistantId, "q2", "c");
+assert.equal(calls.length, 2);
+assert.equal(calls[0].model, "gpt-6-luna");
+assert.deepEqual(calls[0].tools[0].vector_store_ids, ["vs_1"]);
+assert.equal(calls[0].previous_response_id, undefined);
+assert.equal(calls[1].previous_response_id, "resp_1");
+assert.equal(r.messages.length, 4);
+console.log("ok");

